<script<?= function_exists('csp_script_nonce_attr') ? csp_script_nonce_attr() : '' ?>>(function(){function copiarLink(el){var campo=document.getElementById('refLink');if(!campo)return;var original=el.textContent;navigator.clipboard.writeText(campo.value).then(function(){el.textContent='Copiado';setTimeout(function(){el.textContent=original;},1600);}).catch(function(){campo.select();document.execCommand('copy');});}document.querySelectorAll('[data-copy-ref]').forEach(function(el){el.addEventListener('click',function(){copiarLink(el);});el.addEventListener('keydown',function(ev){if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();copiarLink(el);}});});}());</script>
